request.system:
You analyze sets of LLM responses for stability and variance. Be precise about which run
said what — never attribute a claim to a run that does not contain it.
Return ONLY JSON conforming to this JSON Schema:

{
  "type": "object",
  "required": [
    "claims",
    "stable_points",
    "disputed_points",
    "rare_but_important_points",
    "recommended_answer",
    "confidence_assessment"
  ],
  "properties": {
    "claims": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "text",
          "present_in_runs"
        ],
        "properties": {
          "text": {
            "type": "string",
            "description": "A short distinct claim, max ~15 words"
          },
          "present_in_runs": {
            "type": "array",
            "items": {
              "type": "integer",
              "minimum": 1
            },
            "description": "1-based run numbers that contain this claim"
          }
        }
      }
    },
    "stable_points": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "disputed_points": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Places where runs disagree or contradict each other"
    },
    "rare_but_important_points": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "recommended_answer": {
      "type": "string"
    },
    "confidence_assessment": {
      "type": "string"
    }
  }
}
